function requestTrashClear(kind,projectId){
  let request,entries,summary,title;
  if(kind==='projects'){
    const deleted=projects.filter(p=>p.deleted_at);
    if(!deleted.length)return toast('回收站已为空。');
    request={kind,projectIds:deleted.map(p=>p.id)};
    entries=deleted.map(p=>`${titleOf(p)}（${p.tasks.length} 项子任务）`);
    summary=`将永久删除 ${deleted.length} 个已删除大任务，以及其中 ${deleted.reduce((count,p)=>count+p.tasks.length,0)} 项子任务、原文和材料记录。`;
    title='清空大任务回收站？';
  }else{
    const selected=projectId?activeProjects().filter(p=>p.id===projectId):activeProjects();
    const targets=selected.map(p=>({projectId:p.id,taskIds:p.tasks.filter(t=>t.deleted_at).map(t=>t.id)})).filter(item=>item.taskIds.length);
    entries=selected.flatMap(p=>p.tasks.filter(t=>t.deleted_at).map(t=>`${t.title} · ${titleOf(p)}`));
    if(!entries.length)return toast('回收站已为空。');
    request={kind:'tasks',projectId,targets};
    summary=`将永久删除 ${entries.length} 项已删除子任务，所属大任务继续保留。`;
    title=projectId?'清空此大任务的子任务回收站？':'清空子任务回收站？';
  }
  modal(`<div class="eyebrow">永久清理</div><h2>${title}</h2><p class="muted">${esc(summary)}</p><ul class="plain-list trash-scope-list">${entries.slice(0,5).map(label=>`<li>${esc(label)}</li>`).join('')}</ul>${entries.length>5?`<p class="muted">另有 ${entries.length-5} 项记录。</p>`:''}<p class="trash-warning">清空后无法恢复。清理范围为本浏览器保存的回收站记录。</p><div class="modal-actions"><button class="button secondary" data-action="cancel-empty-trash">取消</button><button class="button delete-task-confirm" data-action="confirm-empty-trash">永久清空</button></div>`);
  pendingTrashAction=request;
}
function commitTrashClear(){
  const request=pendingTrashAction;if(!request)return toast('请重新打开回收站确认清理范围。');
  try{
    let nextProjects=structuredClone(projects),removed=0;
    if(request.kind==='projects'){
      const result=purgeProjectTrash(nextProjects,request.projectIds);
      nextProjects=result.projects;removed=result.removedProjects;
    }else{
      for(const target of request.targets){
        const p=nextProjects.find(p=>p.id===target.projectId);
        if(p)removed+=purgeTaskTrash(p,target.taskIds).removedTasks;
      }
    }
    if(!removed)throw Error('这些记录已恢复或已清理，请重新检查回收站。');
    try{localStorage.setItem(KEY,JSON.stringify({version:1,projects:nextProjects}));}catch{throw Error('清理未能保存，回收站内容已保留，请检查浏览器存储后重试。');}
    projects=nextProjects;closeModal();
    if(currentView().startsWith('project/')&&!projectById(decodeURIComponent(currentView().slice(8))))navigate('overview');
    else render();
    if(request.kind==='projects')showDeletedProjects();
    else showDeletedTasks(request.projectId);
    toast(`已永久清空 ${removed} ${request.kind==='projects'?'个大任务':'项子任务'}。`);
  }catch(error){toast(error.message);}
}
function artifactGrid(p){
  const texts=p.artifactTexts||{},names=[...new Set([...Object.keys(texts),...(p.artifacts||[]).map(a=>a.path.split('/').pop())])].filter(x=>!['文献台账.csv','资料收集计划.md','办理核对表.md','PPT制作任务书.md','PPT生成提示词.md'].includes(x));
  return `<div class="artifact-intro">${icon('folder')}<p>可查看或下载已有草稿。PPT 的制作任务书与生成提示词统一放在“PPT制作”中。</p></div><div class="artifact-grid">${names.map(name=>{
    const ready=Boolean(texts[name]),isPPT=name.endsWith('.pptx');
    return `<article class="panel artifact-card"><span class="artifact-file-icon ${isPPT?'orange':''}">${icon(isPPT?'grid':'file')}</span><span class="status-tag ${ready?'success':''}">${ready?'草稿可查看':'待制作'}</span><h3>${isPPT?'PPT制作':esc(name)}</h3><p>${ready?'已根据当前要求整理，可继续补充完善。':'需要结合通知内容生成实际文件并检查。'}</p>${isPPT?`<div class="artifact-prompt-note">${icon('spark')}<span>含制作任务书与生成提示词</span></div>`:''}<button class="button ${ready?'secondary':'ghost'}" data-action="artifact" data-project="${esc(p.id)}" data-name="${esc(name)}">${ready?'查看草稿':'查看制作要求'} ${icon('arrow')}</button></article>`;
  }).join('')}</div>`;
}
