function resourcesView(){return `${pageTitle('资料与产物','让准备工作，留下可继续使用的成果。','查看当前事项的提纲、材料草稿与待制作文件。')} ${activeProjects().map(p=>`<section class="resources-section"><div class="section-heading"><h2>${esc(titleOf(p))}</h2><button class="text-button" data-action="project" data-id="${esc(p.id)}">查看事项 ${icon('arrow')}</button></div>${artifactGrid(p)}</section>`).join('')||'<div class="empty-state">导入事项后，对应材料会出现在这里。</div>'}`;}

function render(){const view=currentView(),nav=view.startsWith('project/')?'overview':view;document.getElementById('app').innerHTML=`<div class="app-shell ${mobileMenu?'menu-open':''}"><aside class="sidebar"><a class="brand" href="#overview"><span class="brand-mark">序</span><span><strong>课序</strong><small>CAMPUS FLOW</small></span></a><div class="workspace-label">学生工作台</div><nav aria-label="主要导航">${[['overview','grid','工作台'],['inbox','inbox','通知收件箱'],['timeline','calendar','完成时间表'],['library','flow','流程库'],['resources','folder','资料与产物']].map(([key,ic,label])=>`<a href="#${key}" class="nav-item ${nav===key?'active':''}">${icon(ic)}<span>${label}</span>${key==='inbox'?'<span class="nav-plus">+</span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="workspace-state"><span class="green-dot"></span>网页测试空间</div><p>修改保存在当前浏览器<br>可导出，不改变原始台账</p><button class="sidebar-export" data-action="export-all">${icon('download')} 导出测试数据</button><div class="user-block"><span class="avatar">同</span><span><strong>同学，你好</strong><small>按自己的节奏，一步一步来</small></span></div></div></aside><div class="main-shell"><header class="topbar"><button class="icon-button mobile-toggle" data-action="menu" aria-label="展开导航">${icon('menu')}</button><span class="breadcrumb">我的校园 <span>/</span> ${({'overview':'工作台','inbox':'通知收件箱','timeline':'完成时间表','library':'流程库','resources':'资料与产物'})[nav]||'事项详情'}</span><div class="topbar-actions"><span class="test-mode">${icon('clock')} 浏览器测试</span><button class="text-button reset-button" data-action="reset">恢复初始数据</button></div></header><main id="main">${view==='overview'?overview():view==='inbox'?importView():view==='timeline'?timelineView():view==='library'?libraryView():view==='resources'?resourcesView():view.startsWith('project/')?detailView(decodeURIComponent(view.slice(8))):overview()}<footer class="page-footer"><span>课序 · 从通知到行动</span><span>内容分流 · 材料准备 · 完成时间表</span></footer></main></div></div>`;bindView();}
function bindView(){const form=document.getElementById('import-form');if(form){form.addEventListener('input',captureDraft);form.addEventListener('change',captureDraft);form.addEventListener('submit',e=>{e.preventDefault();captureDraft();if(!draft.text.trim()){toast('请先导入文件或粘贴正文。');return;}draft.decision=detect(draft.text,data.catalog);draft.types=[...draft.decision.types];render();document.getElementById('classification-preview').scrollIntoView({behavior:'smooth',block:'nearest'});});document.getElementById('file-input').addEventListener('change',e=>readFile(e.target.files[0]));const zone=document.getElementById('drop-zone');zone.addEventListener('dragover',e=>{e.preventDefault();zone.classList.add('dragging');});zone.addEventListener('dragleave',()=>zone.classList.remove('dragging'));zone.addEventListener('drop',e=>{e.preventDefault();zone.classList.remove('dragging');readFile(e.dataTransfer.files[0]);});}document.getElementById('task-search')?.addEventListener('input',e=>{const cursor=e.target.selectionStart;query=e.target.value;render();const input=document.getElementById('task-search');input.focus();input.setSelectionRange(cursor,cursor);});document.querySelectorAll('input[name="workflow-type"]').forEach(input=>input.addEventListener('change',()=>{if(input.checked){if(['general','information_only'].includes(input.value))draft.types=[input.value];else draft.types=[...draft.types.filter(x=>!['general','information_only'].includes(x)),input.value];}else draft.types=draft.types.filter(x=>x!==input.value);render();}));}
function captureDraft(){const previous=draft.text,signature=JSON.stringify([draft.title,draft.topic,draft.role,draft.deadline,draft.eventDate]);const form=document.getElementById('import-form');if(!form)return;for(const [key,value] of new FormData(form))draft[key]=value;if(previous!==draft.text){draft.fingerprint='';draft.decision=null;const preview=document.getElementById('classification-preview');if(preview)preview.innerHTML='<h2>分流预览</h2><p class="muted">正文已修改，请重新识别类型后查看提示词。</p>';}else if(draft.decision&&signature!==JSON.stringify([draft.title,draft.topic,draft.role,draft.deadline,draft.eventDate]))refreshPPTPrompt();}
async function readFile(file){
  if(!file)return;
  captureDraft();
  if(file.size>10*1024*1024){toast('文件超过 10 MB，请精简后重试或粘贴正文。');return;}
  try{
    toast('正在读取 '+file.name+'…');
    const bytes=await file.arrayBuffer();const hash=await crypto.subtle.digest('SHA-256',bytes);let text,readMeta='',readWarnings=[];
    if(/\.pdf$/i.test(file.name)){
      const result=await readPDF(bytes,(page,total)=>{const element=document.getElementById('toast');element.textContent=`正在读取 PDF：第 ${page} / ${total} 页`;});
      text=result.text;readMeta=`PDF 已读取 ${result.pageCount} 页，正文保留页码。`;readWarnings=result.warnings;
     }else if(/\.(pptx|pptm|ppsx)$/i.test(file.name)){
      const result=await readPPTX(bytes,(page,total)=>{document.getElementById('toast').textContent=`正在读取 PowerPoint：第 ${page} / ${total} 页`;});
      text=result.text;readMeta=`PowerPoint 已读取 ${result.pageCount} 页，${result.notesCount} 页含演讲者备注，正文保留页码。`;readWarnings=result.warnings;
    }else if(/\.ppt$/i.test(file.name)){
      throw Error('旧版 PPT 暂不能直接读取，请在 PowerPoint 中另存为 PPTX，或导出 PDF 后导入。');
    }else if(/\.docx$/i.test(file.name)){
      const archive=await window.JSZip.loadAsync(bytes),entry=archive.file('word/document.xml');
      if(!entry)throw Error('文件不是可读取的 DOCX 文档。');
      const xml=await entry.async('string');if(xml.length>8000000)throw Error('文档正文过大，请分段粘贴。');
      const doc=new DOMParser().parseFromString(xml,'application/xml');if(doc.querySelector('parsererror'))throw Error('文档内部结构无法解析。');
      const ns='http://schemas.openxmlformats.org/wordprocessingml/2006/main';
      text=[...doc.getElementsByTagNameNS(ns,'p')].map(p=>[...p.getElementsByTagNameNS(ns,'t')].map(t=>t.textContent).join('')).join('\n');
      readMeta='Word 文档正文已读取，请对照原文核对图片与附件中的要求。';
    }else if(/\.(txt|md)$/i.test(file.name))text=new TextDecoder('utf-8',{fatal:true}).decode(bytes);
    else throw Error('当前支持 PDF、PPTX、PPTM、PPSX、DOCX、TXT 和 Markdown；旧版 PPT 请先另存为 PPTX 或 PDF。');
    if(!text.trim())throw Error('文件中未找到可读取的正文。');
    draft.fingerprint=[...new Uint8Array(hash)].map(b=>b.toString(16).padStart(2,'0')).join('');
    Object.assign(draft,{title:file.name.replace(/\.[^.]+$/,''),text,filename:file.name,decision:null,readMeta,readWarnings,readError:''});
    render();toast(readWarnings.length?'正文已读取，部分页面需要核对。':'文件正文已读取，核对日期后即可测试分流。');
  }catch(error){draft.readError=file.name+'：'+(error.message||'文件读取失败，请改为粘贴正文。')+(draft.text?' 当前保留上一份已读取的内容。':'');render();toast('文件未导入，请查看读取提示。');}
}
function sample(kind){const today=todayShanghai();const examples={meeting:{title:'诚信应考主题班会（示例）',text:`【虚构测试示例】\n请组织召开“诚信应考”主题班会，活动时间为${addDays(today,7)}，面向全班同学，时长约30分钟。请准备主题PPT、主持稿、签到表和讨论题，会后整理真实会议记录与照片。`,eventDate:addDays(today,7),deadline:addDays(today,6),role:'organizer',topic:'诚信应考'},group:{title:'校园节能调研小组作业（示例）',text:`【虚构测试示例】\n本次小组作业每组4人，自由组队。围绕校园节能完成课程论文，并制作汇报PPT。需查找相关论文、实际调研资料和数据来源。请于${addDays(today,14)}提交小组报告与PPT。`,deadline:addDays(today,14),role:'auto',teamSize:'4',topic:'校园节能调研'},paper:{title:'个人课程论文（示例）',text:`【虚构测试示例】\n独立完成一篇个人论文，自拟题目，报告不少于3000字，参考文献至少15篇。文献类型与年份按课程要求核查。${addDays(today,14)}前提交。检索过程参考教学PPT，不要求另做展示。`,deadline:addDays(today,14),topic:''}};draft={title:'',text:'',deadline:'',eventDate:'',role:'auto',topic:'',teamSize:'',types:[],decision:null,filename:'',fingerprint:'',...examples[kind]};draft.decision=detect(draft.text,data.catalog);draft.types=[...draft.decision.types];navigate('inbox');render();}
function makeTexts(p){const labels=p.types.map(x=>data.catalog[x].name).join(' + '),topic=p.topic||'待确定';let result={'需求与产物.md':`# ${p.title}\n\n流程：${labels}\n当前主题：${topic}\n正式截止：${p.deadline||'待确认'}\n\n## 当前要求\n\n${p.sourceText}\n\n## 执行过程\n\n${p.tasks.map((t,i)=>`${i+1}. ${t.title}：建议 ${t.planning.start_on||'待确认'} 至 ${t.planning.finish_on||'待确认'}`).join('\n')}`,'资料收集计划.md':`# 资料收集计划\n\n主题：${topic}\n\n1. 优先获取教师课件、教材和原通知。\n2. 将主题拆成对象、问题、方法和场景，整理中英文关键词。\n3. 实际检索原始资料，记录链接、年份、类型、推荐理由和全文状态。\n4. 核对文献数量与其他硬性要求，不把未查阅材料计入成果。\n\n${data.resources.filter(x=>x.url).map(x=>`- ${x.name}：${x.url}\n  用途：${x.purpose}`).join('\n')}\n\n当前是收集计划，不代表已查阅或取得全文。`};
if(p.types.includes('academic_writing'))result['写作提纲.md']=`# 写作提纲\n\n题目：${topic}\n\n1. 研究问题与选题意义：研究对象、范围、价值和关键词。\n2. 文献与检索方案：数据库、检索式、筛选标准、资料整理。\n3. 分析与论证：按子问题组织真实证据，说明方法和局限。\n4. 讨论与结论：用证据回答研究问题，不预设结果。\n5. 参考文献：核对真实书目信息与引用位置。\n\n以上为可调整的建议结构，原文件已有模板时应优先按模板要求细化。`;
if(p.types.includes('group_assignment')||p.types.includes('competition_project'))result['分组需求.md']=`# 分组与职责需求\n\n已确认人数：${p.teamSize||'待确认'}\n\n| 职责 | 负责人 | 应交成果 | 复核人 |\n| --- | --- | --- | --- |\n| 统筹与要求核对 | 待分配 | 进度与统一版本 | 待分配 |\n| 检索与证据整理 | 待分配 | 资料清单与出处 | 待分配 |\n| 分析或实现 | 待分配 | 分析、代码或设计 | 待分配 |\n| 写作与整合 | 待分配 | 报告草稿 | 待分配 |\n| 展示与核验 | 待分配 | 展示材料与检查记录 | 待分配 |\n\n一人可兼任多个职责；姓名和成员承诺需实际确认。`;
if(p.types.includes('class_meeting')&&p.role!=='participant')result['班会材料草稿.md']=`# ${topic}班会材料草稿\n\n## 议程\n\n开场与目标说明、主题学习、案例讨论、行动总结。按实际时长细化。\n\n## 主持稿提纲\n\n介绍主题与目的，说明讨论问题，串联各环节，汇总实际意见。具体讲稿需结合原始材料完善。\n\n## 签到与记录模板\n\n日期：待填写\n地点：待填写\n主持人：待填写\n应到与实到：待实际发生后填写\n讨论内容与实际决定：待记录\n真实照片与提交回执：待补充\n\n不得把上述空模板当作会议已经完成的证明。`;
if(p.types.includes('class_meeting')&&p.role==='participant')result['参会准备.md']='# 参会准备\n\n核对实际日期、地点和应阅读材料。仅准备通知要求的个人内容。出勤、会议记录和心得按实际要求与发生情况填写。';
if(needsPPT(p,data.catalog))result['PPT生成提示词.md']=p.pptPrompt||buildPPTPrompt(p,data.catalog,data.pptPromptSpec);
if(p.artifacts.some(a=>a.path.endsWith('.pptx')))result['PPT制作任务书.md']=`# PPT制作任务书\n\n主题：${topic}\n\n核对听众、时长、页数、必讲内容和引用来源后制作真正的PPTX。补充讲稿或备注，并渲染逐页检查溢出、字体与可读性。\n\n本页只保存任务书，不表示实际PPT已经生成。回到聊天提供此事项即可继续制作。`;
return result;}
function createProject(){captureDraft();const d=draft;if(!d.types.length)return toast('至少选择一种流程。');const existing=activeProjects().find(p=>d.fingerprint&&p.fingerprint===d.fingerprint);if(existing){navigate('project/'+existing.id);return toast('这份文件已经存在，已打开原有事项。');}const match=d.text.match(/(?:每组|一组)\s*(\d+)\s*人|(\d+)\s*人一组/);const prescribed=match?Number(match[1]||match[2]):null;const teamSize=d.teamSize?Number(d.teamSize):prescribed;if(prescribed&&teamSize!==prescribed)return toast(`正文规定每组${prescribed}人，请核对小组人数。`);const role=d.role==='auto'?d.decision.role:d.role;const composed=adaptPPTStages(composeStages(d.types,role,data.catalog,data.stages),needsPPT({...d,role},data.catalog));const result=schedule(composed,todayShanghai(),d.deadline,d.eventDate,Math.max(...d.types.map(k=>data.catalog[k].default_days)));const id=crypto.randomUUID();const p={id,title:d.title.trim()||'未命名校园事项',types:[...d.types],role,topic:d.topic.trim(),teamSize,deadline:d.deadline||null,eventDate:d.eventDate||null,createdOn:todayShanghai(),sourceText:d.text,fingerprint:d.fingerprint,isSeed:false,tasks:result.tasks.map(t=>({...t,id:id+':'+t.id,depends_on:t.depends_on.map(x=>id+':'+x)})),followups:[...result.warnings,...(d.readWarnings||[])].map(item=>({item,blocking:'按实际信息补充或调整，建议日期不代表官方要求。',status:'unknown'})),artifacts:[]};for(const type of p.types){if(type==='class_meeting'&&role==='participant')continue;for(const [filename,handler,acceptance] of data.catalog[type].artifacts){if(filename.endsWith('.pptx')&&!needsPPT(p,data.catalog))continue;if(filename.endsWith('.pptx')&&type==='competition_project'&&!/PPT|路演|答辩/i.test(d.text))continue;if(!p.artifacts.some(a=>a.path===filename))p.artifacts.push({path:filename,status:'planned',handler,acceptance});}}p.pptPrompt=needsPPT(p,data.catalog)?(document.getElementById('ppt-prompt-preview')?.value||buildPPTPrompt(p,data.catalog,data.pptPromptSpec)):'';p.artifactTexts=makeTexts(p);projects.unshift(p);save();detailTab='tasks';navigate('project/'+id);toast('工作包与建议时间表已生成，保存在当前浏览器。');}

function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function modal(content){pendingTrashAction=null;document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="详情"><button class="icon-button modal-close" data-action="close-modal" aria-label="关闭">${icon('close')}</button>${content}</section></div>`;document.querySelector('.modal button')?.focus();}
function closeModal(){pendingTrashAction=null;document.getElementById('modal-root').innerHTML='';}
function markdown(text){return text.split('\n').map(line=>line.startsWith('# ')?`<h2>${esc(line.slice(2))}</h2>`:line.startsWith('## ')?`<h3>${esc(line.slice(3))}</h3>`:line.trim()?`<p>${esc(line)}</p>`:'<div class="paragraph-gap"></div>').join('');}
document.addEventListener('click',e=>{
  const button=e.target.closest('[data-action]');if(!button)return;
  const action=button.dataset.action;
  if(action==='empty-project-trash'){requestTrashClear('projects');return;}
  if(action==='empty-task-trash'){requestTrashClear('tasks',button.dataset.project);return;}
  if(action==='confirm-empty-trash'){commitTrashClear();return;}
  if(action==='cancel-empty-trash'){const request=pendingTrashAction;if(request?.kind==='projects')showDeletedProjects();else if(request)showDeletedTasks(request.projectId);else closeModal();return;}
  if(action==='deleted-tasks'){showDeletedTasks(button.dataset.project);return;}
  if(action==='deleted-projects'){showDeletedProjects();return;}
  if(!['delete-project','confirm-delete-project','restore-project','set-task-status','delete-task','confirm-delete-task','restore-task'].includes(action))return;
  const p=projectById(button.dataset.project),t=p?.tasks.find(task=>task.id===button.dataset.task);
  if(action==='delete-project'){
    if(!p||p.deleted_at)return toast('未找到可删除的大任务。');
    modal(`<div class="eyebrow">删除整个大任务</div><h2>删除这个大任务？</h2><p class="muted"><strong>${esc(titleOf(p))}</strong><br>包含 ${p.tasks.length} 项子任务及对应材料。</p><p class="muted">删除后会从工作台、时间表和资料列表移除，可在工作台的“已删除大任务”中恢复。</p><div class="modal-actions"><button class="button secondary" data-action="close-modal">取消</button><button class="button delete-task-confirm" data-action="confirm-delete-project" data-project="${esc(p.id)}">确认删除大任务</button></div>`);
    return;
  }
  if(action==='delete-task'){
    if(!p||p.deleted_at||!t||t.deleted_at)return toast('未找到可删除的任务。');
    modal(`<div class="eyebrow">删除子任务</div><h2>删除这项任务？</h2><p class="muted"><strong>${esc(t.title)}</strong><br>${esc(titleOf(p))}</p><p class="muted">删除后从列表移除，可在“已删除任务”中恢复。</p><div class="modal-actions"><button class="button secondary" data-action="close-modal">取消</button><button class="button delete-task-confirm" data-action="confirm-delete-task" data-project="${esc(p.id)}" data-task="${esc(t.id)}">确认删除</button></div>`);
    return;
  }
  try{
    if(!p)throw Error('未找到对应任务。');
    if(action==='set-task-status'){
      setTaskStatus(p,button.dataset.task,button.dataset.status);save();render();
      toast(button.dataset.status==='completed'?'已标记为已完成。':'已设为待办。');return;
    }
    if(action==='confirm-delete-project')deleteProject(projects,p.id);
    else if(action==='restore-project')restoreProject(projects,p.id);
    else if(action==='confirm-delete-task')deleteTask(p,button.dataset.task);
    else restoreDeletedTask(p,button.dataset.task);
    save();closeModal();
    if(action==='confirm-delete-project')navigate('overview');
    else render();
    toast(action==='confirm-delete-project'?'大任务已删除，可在工作台恢复。':action==='restore-project'?'大任务已恢复。':action==='confirm-delete-task'?'子任务已删除，可在“已删除任务”中恢复。':'子任务已恢复。');
  }catch(error){toast(error.message);}
});

function artifactModal(p,name){
  const text=p.artifactTexts?.[name],acceptance=p.artifacts?.find(a=>a.path.endsWith(name))?.acceptance||'按文件要求完成并检查。';
  if(name.endsWith('.pptx')){
    const prompt=p.pptPrompt||p.artifactTexts?.['PPT生成提示词.md']||buildPPTPrompt(p,data.catalog,data.pptPromptSpec);
    const brief=p.artifactTexts?.['PPT制作任务书.md'];
    p.artifactTexts=p.artifactTexts||{};p.artifactTexts['PPT生成提示词.md']=prompt;
    modal(`<div class="eyebrow">制作任务书 · 生成提示词</div><h2>PPT制作</h2><p class="muted">${text?'已有内容草稿，可结合以下提示词继续制作和检查。':'PPT 文件尚未生成。可在这里查看制作任务书，复制生成提示词到聊天或 PPT 生成工具继续制作。'}</p><h3 class="small-heading">完成标准</h3><p class="muted">${esc(acceptance)}</p>${brief?`<details class="ppt-task-brief"><summary>制作任务书</summary><div class="document-preview" aria-label="PPT制作任务书">${markdown(brief.replace(/^# PPT制作任务书\s*\n/,''))}</div></details>`:''}${text?`<details><summary>查看已有内容草稿</summary><div class="document-preview">${markdown(text)}</div></details>`:''}<h3 class="small-heading">PPT 生成提示词</h3><div class="document-preview" aria-label="PPT生成提示词">${markdown(prompt.replace(/^# PPT生成提示词\s*\n/,''))}</div><div class="ppt-artifact-actions"><button class="button primary" data-action="copy-ppt-project" data-project="${esc(p.id)}">复制提示词</button><button class="button secondary" data-action="download-artifact" data-project="${esc(p.id)}" data-name="PPT生成提示词.md">${icon('download')} 下载提示词</button></div>`);
    return;
  }
  modal(`<div class="eyebrow">${text?'工作包草稿':'待制作产物'}</div><h2>${esc(name)}</h2>${text?`<div class="document-preview">${markdown(text)}</div><button class="button primary" data-action="download-artifact" data-project="${esc(p.id)}" data-name="${esc(name)}">${icon('download')} 下载草稿</button>`:`<p class="muted">此文件尚未生成。请把要求带回当前聊天，继续完成实际制作和检查。</p><div class="document-preview"><p>${esc(acceptance)}</p></div><button class="button primary" data-action="copy-prompt" data-project="${esc(p.id)}" data-name="${esc(name)}">复制执行指令 ${icon('arrow')}</button>`}`);
}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button)return;const a=button.dataset.action;if(a==='copy-ppt-preview')await copyPromptText(document.getElementById('ppt-prompt-preview')?.value||buildPPTPrompt(draftPPTContext(),data.catalog,data.pptPromptSpec));if(a==='download-ppt-preview')download('PPT生成提示词.txt',document.getElementById('ppt-prompt-preview')?.value||buildPPTPrompt(draftPPTContext(),data.catalog,data.pptPromptSpec));if(a==='copy-ppt-project'){const p=projectById(button.dataset.project);await copyPromptText(p.pptPrompt||buildPPTPrompt(p,data.catalog,data.pptPromptSpec));}if(a==='navigate')navigate(button.dataset.view);if(a==='project'){detailTab='tasks';navigate('project/'+button.dataset.id);}if(a==='sample')sample(button.dataset.kind);if(a==='create-project')createProject();if(a==='menu'){mobileMenu=!mobileMenu;render();}if(a==='detail-tab'){detailTab=button.dataset.tab;render();}if(a==='filter'){filter=button.dataset.filter;render();}if(a==='close-modal'||a==='backdrop'&&e.target===button)closeModal();if(a==='artifact')artifactModal(projectById(button.dataset.project),button.dataset.name);if(a==='download-artifact'){const p=projectById(button.dataset.project);download(button.dataset.name,p.artifactTexts[button.dataset.name]);}if(a==='export-all')download('课序-网页测试数据.json',JSON.stringify({exportedAt:new Date().toISOString(),projects},null,2),'application/json');if(a==='export-project'){const p=projectById(button.dataset.id);download(titleOf(p)+'-工作包.json',JSON.stringify(p,null,2),'application/json');}if(a==='export-calendar'){download('课序-截止日历.ics',makeICS(projects),'text/calendar;charset=utf-8');toast('已导出已知截止，未包含阶段建议日期。');}if(a==='reset')modal('<div class="eyebrow">恢复测试空间</div><h2>恢复初始数据？</h2><p class="muted">将清除本浏览器中的测试导入和状态修改。原始工作流台账不受影响，可先导出测试数据。</p><div class="modal-actions"><button class="button secondary" data-action="close-modal">保留当前数据</button><button class="button primary" data-action="confirm-reset">恢复初始数据</button></div>');if(a==='confirm-reset'){projects=structuredClone(data.projects);projects.forEach(p=>{normalizeProjectState(p);ensurePPTPrompt(p);});save();closeModal();navigate('overview');render();toast('已恢复初始测试数据。');}if(a==='workflow'){const key=button.dataset.kind,item=data.catalog[key];modal(`<div class="eyebrow">流程库</div><h2>${esc(item.name)}</h2><h3 class="small-heading">先核对这些信息</h3><ul class="plain-list">${item.inputs.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3 class="small-heading">主要产物</h3><ul class="plain-list">${item.artifacts.map(([name,,check])=>`<li><strong>${esc(name)}</strong><p>${esc(check)}</p></li>`).join('')}</ul><button class="button primary" data-action="close-and-import">导入文件开始测试 ${icon('arrow')}</button>`);}if(a==='close-and-import'){closeModal();navigate('inbox');}if(a==='copy-prompt'){const p=projectById(button.dataset.project);const prompt=button.dataset.name?.endsWith('.pptx')?(p.pptPrompt||buildPPTPrompt(p,data.catalog,data.pptPromptSpec)):`按校园分类工作流继续处理“${p.title}”。流程：${p.types.map(x=>data.catalog[x].name).join('、')}。主题：${p.topic||'待确认'}。截止：${p.deadline||'待确认'}。请结合原始要求实际生成对应材料并核验，保留未确认内容。\n\n原文：\n${p.sourceText}`;try{await navigator.clipboard.writeText(prompt);toast('执行指令已复制，可粘贴回聊天继续制作。');}catch{modal(`<h2>执行指令</h2><textarea class="copy-area" readonly>${esc(prompt)}</textarea><p class="muted">请选中并复制到当前聊天。</p>`);}}if(a==='resolve-issue'){const p=projectById(button.dataset.project),issue=p.followups[Number(button.dataset.index)];modal(`<div class="eyebrow">补充事项信息</div><h2>${esc(issue.item)}</h2><form id="issue-form"><label>已确认的信息<textarea name="answer" rows="4" required placeholder="记录实际已知信息…">${esc(issue.answer||'')}</textarea></label><p class="field-note">仅记录本项补充，不会自动改写原文或正式截止。</p><button class="button primary full" type="submit">保存补充</button></form>`);document.getElementById('issue-form').addEventListener('submit',event=>{event.preventDefault();const value=new FormData(event.target).get('answer').trim();if(!value)return;issue.answer=value;issue.status='resolved';save();closeModal();render();toast('补充信息已记录。');});}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&document.querySelector('.modal')){const elements=[...document.querySelectorAll('.modal button,.modal input,.modal select,.modal textarea,.modal a')].filter(x=>!x.disabled);const first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{mobileMenu=false;render();window.scrollTo({top:0});});
try{const response=await fetch('./data.json');if(!response.ok)throw Error('工作流数据暂时无法载入。');data=await response.json();let saved;try{saved=JSON.parse(localStorage.getItem(KEY)||'null');}catch{}projects=saved?.version===1&&Array.isArray(saved.projects)?saved.projects:structuredClone(data.projects);projects.forEach(p=>{normalizeProjectState(p);ensurePPTPrompt(p);});save();render();}catch(error){document.getElementById('app').innerHTML=`<div class="loading-screen"><h1>工作台暂时无法载入</h1><p>${esc(error.message)}</p><button class="button primary" onclick="location.reload()">重新载入</button></div>`;}
